-- === P1-13: transactional outbox / inbox ===

CREATE TABLE careers.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    CONSTRAINT pk_careers_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE careers.outbox_event IS 'Transactional outbox of the careers module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN careers.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN careers.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN careers.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN careers.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN careers.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN careers.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN careers.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN careers.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
CREATE INDEX ix_careers_outbox_event_pending ON careers.outbox_event (id) WHERE published_at IS NULL;
CREATE TABLE careers.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_careers_inbox_event PRIMARY KEY (event_id)
);
COMMENT ON TABLE careers.inbox_event IS 'Inbox of the careers module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN careers.inbox_event.event_id IS 'Global id of the consumed event.';
COMMENT ON COLUMN careers.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN careers.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN careers.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN careers.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN careers.inbox_event.processing_error IS 'Last handling error, if any.';

